package com.secure.documentwallet;

import android.app.Application;import android.graphics.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.zip.*;import static org.junit.Assert.*;

@RunWith(RobolectricTestRunner.class) @Config(sdk=35,application=Application.class) @org.robolectric.annotation.GraphicsMode(org.robolectric.annotation.GraphicsMode.Mode.NATIVE)
public class VaultSecurityTest {
 Application c;PinSecurity pin;CryptoStore crypto;
 @Before public void setup()throws Exception{c=RuntimeEnvironment.getApplication();c.getSharedPreferences("security",0).edit().clear().commit();pin=new PinSecurity(c);pin.set("1234");Session.unlock("1234",pin.vaultSalt());crypto=new CryptoStore(c);for(File f:crypto.vaultDir().listFiles())f.delete();}
 @After public void clear(){Session.lock();}
 @Test public void pinAndAesGcmProtectVault()throws Exception{assertTrue(pin.verify("1234"));assertFalse(pin.verify("6543"));byte[] privateData="Private ID details".getBytes(StandardCharsets.UTF_8);crypto.encryptBytes(privateData,"secret");byte[] disk=java.nio.file.Files.readAllBytes(new File(crypto.vaultDir(),"secret.sdw").toPath());assertFalse(new String(disk,StandardCharsets.UTF_8).contains("Private ID"));assertArrayEquals(privateData,crypto.decrypt(new File(crypto.vaultDir(),"secret.sdw")));Session.lock();try{crypto.decrypt(new File(crypto.vaultDir(),"secret.sdw"));fail("Locked vault should not decrypt");}catch(SecurityException expected){}}
 @Test public void wordExportContainsBothEncryptedSides()throws Exception{Bitmap b=Bitmap.createBitmap(300,180,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(b);canvas.drawColor(Color.WHITE);Paint p=new Paint();p.setColor(Color.BLACK);p.setTextSize(28);canvas.drawText("IDENTITY DOCUMENT",18,90,p);ByteArrayOutputStream jpg=new ByteArrayOutputStream();b.compress(Bitmap.CompressFormat.JPEG,92,jpg);b.recycle();crypto.encryptBytes(jpg.toByteArray(),"doc-page-1");crypto.encryptBytes(jpg.toByteArray(),"doc-page-2");JSONObject doc=new JSONObject().put("id","doc").put("title","My ID").put("category","Identity").put("pages",new JSONArray().put("doc-page-1").put("doc-page-2"));File word=new DocumentExporter(c).docx(doc,true);assertTrue(word.length()>1000);boolean document=false,image1=false,image2=false;try(ZipInputStream z=new ZipInputStream(new FileInputStream(word))){for(ZipEntry entry;(entry=z.getNextEntry())!=null;){document|="word/document.xml".equals(entry.getName());image1|="word/media/image1.jpg".equals(entry.getName());image2|="word/media/image2.jpg".equals(entry.getName());}}assertTrue(document&&image1&&image2);}
 @Test public void changingPinReencryptsEveryVaultFile()throws Exception{byte[] original="Preserve this encrypted card".getBytes(StandardCharsets.UTF_8);crypto.encryptBytes(original,"migration-card");crypto.rekey("1234","4321",pin.vaultSalt());Session.lock();Session.unlock("4321",pin.vaultSalt());assertArrayEquals(original,crypto.decrypt(new File(crypto.vaultDir(),"migration-card.sdw")));}
}
